import {api,el,button,message,confirmAction} from './common.js';
import {icon} from './ui.js';
import {downloadPng,downloadSvg,printInvitations,downloadAll} from './invitation-export.js';
import {invitationMessage} from './share-message.js';
let guests=[],groups=[];const login=document.querySelector('#login'),dashboard=document.querySelector('#dashboard'),status=document.querySelector('#admin-status');const labels={pending:'Por confirmar',yes:'Confirmado',no:'Não participa'};
function invite(g){const u=new URL('/',location.origin);u.searchParams.set('convite',g.token);return u.href}
function preview(g){const d=el('dialog');d.append(el('h2','Mensagem do convite'));const text=el('textarea');text.value=invitationMessage(g.name,invite(g),g.companion);text.readOnly=true;text.rows=14;text.setAttribute('aria-label','Mensagem para partilhar');d.append(text,button('Fechar',()=>d.close(),'secondary'));d.addEventListener('close',()=>d.remove(),{once:true});document.body.append(d);d.showModal()}
function editForm(title,fields,onSave){const d=el('dialog'),form=el('form');form.append(el('h2',title));const inputs={};for(const [key,label,value,type] of fields){const id='edit-'+key;const l=el('label',label);l.htmlFor=id;const input=el(type==='textarea'?'textarea':type==='select'?'select':'input');input.id=id;if(type==='select'){for(const [v,t]of Object.entries(labels)){const o=el('option',t);o.value=v;input.append(o)}}else if(type!=='textarea')input.type='text';input.value=value;if(key==='name'){input.required=true;input.maxLength=200}if(key==='companion')input.maxLength=200;inputs[key]=input;form.append(l,input)}const actions=el('div',undefined,'actions');actions.append(button('Cancelar',()=>d.close(),'secondary'));const save=el('button','Guardar');save.type='submit';actions.append(save);form.append(actions);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await onSave(Object.fromEntries(Object.entries(inputs).map(([k,i])=>[k,i.value])));d.close();await load()}catch(err){await message(err.message)}finally{save.disabled=false}};d.append(form);d.addEventListener('close',()=>d.remove(),{once:true});document.body.append(d);d.showModal()}
function fillGroups(){for(const [id,first]of [['new-group','Sem grupo'],['group-filter','Todos os grupos']]){const select=document.querySelector('#'+id),value=select.value;select.replaceChildren();const o=el('option',first);o.value=id==='group-filter'?'all':'';select.append(o);for(const name of [...new Set([...groups.map(g=>g.name),...guests.map(g=>g.group_name).filter(Boolean)])]){const x=el('option',name);x.value=name;select.append(x)}if([...select.options].some(o=>o.value===value))select.value=value}}
function groupStats(name){const active=guests.filter(g=>g.active&&(g.group_name||'Sem grupo')===name);const people=active.flatMap(g=>[g.rsvp,...(g.companion?[g.companion_rsvp]:[])]);return {invites:active.length,people:people.length,yes:people.filter(x=>x==='yes').length,pending:people.filter(x=>x==='pending').length,no:people.filter(x=>x==='no').length,unnamed:active.filter(g=>g.is_placeholder).length}}
function renderOverview(){const box=document.querySelector('#group-overview');box.replaceChildren();for(const name of [...new Set([...groups.map(g=>g.name),...guests.map(g=>g.group_name||'Sem grupo')])]){const stats=groupStats(name);const card=button('',()=>{document.querySelector('#group-filter').value=name==='Sem grupo'?'ungrouped':name;renderGuests()},'group-summary');card.append(el('strong',name),el('span',`${stats.people} pessoas${groups.find(g=>g.name===name)?' / '+groups.find(g=>g.name===name).expected_people+' previstas':''} · ${stats.invites} convites`),el('small',`${stats.yes} confirmados · ${stats.pending} pendentes · ${stats.no} não participam${stats.unnamed?' · '+stats.unnamed+' por nomear':''}`));box.append(card)}if(guests.some(g=>!g.group_name)){const o=el('option','Sem grupo');o.value='ungrouped';document.querySelector('#group-filter').append(o)}}
function renderGuests(){const list=document.querySelector('#guests');list.replaceChildren();const q=document.querySelector('#search').value.toLowerCase();const selected=document.querySelector('#group-filter').value;const sections=new Map();for(const g of guests.filter(g=>(selected==='all'||(selected==='ungrouped'?!g.group_name:g.group_name===selected))&&(document.querySelector('#filter').value==='all'||(document.querySelector('#filter').value==='inactive'?!g.active:g.active&&(g.rsvp===document.querySelector('#filter').value||g.companion&&g.companion_rsvp===document.querySelector('#filter').value)))&&(g.name+' '+(g.companion||'')+' '+g.phone).toLowerCase().includes(q))){const card=el('article',undefined,'admin-item');const title=el('div',undefined,'guest-title');title.append(icon('users'),el('h3',g.name+(g.companion?' & '+g.companion:'')),el('span',g.is_placeholder?'Por nomear':g.companion?'2 pessoas':'1 pessoa','tag'));card.append(title,el('p',`${g.name}: ${labels[g.rsvp]}${g.companion?' · '+g.companion+': '+labels[g.companion_rsvp]:''} · ${g.active?'Activo':'Desactivado'}${g.phone?' · '+g.phone:''}`,'small'));const link=el('a','Abrir convite pessoal ↗','small invitation-link');link.href=invite(g);link.target='_blank';link.rel='noopener noreferrer';if(!g.is_placeholder)card.append(link);else card.append(el('p','Edite este lugar e indique o nome antes de partilhar o convite.','small'));const actions=el('div',undefined,'actions');actions.append(button('Ver mensagem',()=>preview(g),'secondary'),button('Copiar convite completo',async()=>{try{await navigator.clipboard.writeText(invitationMessage(g.name,invite(g),g.companion));await message('Mensagem e link pessoal copiados.')}catch{preview(g)}}),button('Copiar apenas link',async()=>{try{await navigator.clipboard.writeText(invite(g));await message('Link copiado.')}catch{await message(invite(g))}}),button('Editar',()=>editForm('Editar convidado',[['name','Primeiro convidado *',g.name],['companion','Acompanhante (opcional)',g.companion||''],['group_name','Grupo',g.group_name||''],['phone','Telefone',g.phone],['rsvp','Presença do primeiro convidado',g.rsvp,'select'],['companion_rsvp','Presença do acompanhante',g.companion_rsvp||'pending','select']],b=>api('/api/admin/guests/'+g.id,{method:'PATCH',body:b})),'secondary'),button(g.active?'Desactivar':'Reactivar',async()=>{if(!await confirmAction(g.active?'Desactivar este convite? As reservas ainda não compradas serão libertadas.':'Reactivar este convite?'))return;await api('/api/admin/guests/'+g.id,{method:'PATCH',body:{active:!g.active}});await load()},'secondary'));{const a=el('a','Partilhar no WhatsApp','btn secondary');let phone=g.phone.replace(/\D/g,'');if(phone.length===9)phone='258'+phone;a.href='https://wa.me/'+(phone||'')+'?text='+encodeURIComponent(invitationMessage(g.name,invite(g),g.companion));a.target='_blank';a.rel='noopener noreferrer';actions.append(a)}if(g.is_placeholder){[...actions.children].forEach((child,i)=>{if(i<3||child.tagName==='A')child.hidden=true})}if(!g.is_placeholder){actions.append(button('Baixar convite PNG',()=>downloadPng(g)),button('Baixar para impressão (SVG)',()=>downloadSvg(g),'secondary'),button('Imprimir / PDF',()=>printInvitations([g]),'secondary'))}card.append(actions);const group=g.group_name||'Sem grupo';if(!sections.has(group)){const section=el('details',undefined,'guest-group');section.open=true;const stats=groupStats(group);const summary=el('summary',`${group} — ${stats.people} pessoas · ${stats.yes} confirmadas`);section.append(summary);sections.set(group,section);list.append(section)}sections.get(group).append(card)}if(!list.childNodes.length)list.append(el('p','Ainda não há convites nesta selecção.'))}
async function load(){try{const [data,groupData]=await Promise.all([api('/api/admin/guests'),api('/api/admin/groups')]);guests=data.guests;groups=groupData.groups;fillGroups();renderOverview();login.hidden=true;dashboard.hidden=false;status.textContent='';const active=guests.filter(g=>g.active);const people=active.flatMap(g=>[g.rsvp,...(g.companion?[g.companion_rsvp]:[])]);const stats=document.querySelector('#stats');stats.replaceChildren(...[['Convites activos',active.length],['Pessoas convidadas',people.length],['Presenças confirmadas',people.filter(r=>r==='yes').length],['Por confirmar',people.filter(r=>r==='pending').length]].map(([l,n])=>{const card=el('article');card.append(el('strong',String(n)),el('span',l));return card}));renderGuests();const {gifts}=await api('/api/admin/gifts'),list=document.querySelector('#admin-gifts');list.replaceChildren();for(const g of gifts){const card=el('article',undefined,'card');card.append(icon('gift'),el('h3',g.name),el('p',g.description),el('p',`${{available:'Disponível',reserved:'Reservado',purchased:'Comprado'}[g.status]}${g.guest_name?' · '+g.guest_name+(g.guest_companion?' & '+g.guest_companion:''):''}`));const actions=el('div',undefined,'actions');actions.append(button('Editar',()=>editForm('Editar presente',[['name','Nome',g.name],['description','Descrição',g.description,'textarea']],b=>api('/api/admin/gifts/'+g.id,{method:'PATCH',body:b})),'secondary'));if(g.status!=='available')actions.append(button('Tornar disponível',async()=>{if(!await confirmAction('Tornar este presente disponível? A reserva ou confirmação de compra será removida.'))return;await api('/api/admin/gifts/'+g.id,{method:'PATCH',body:{reset:true}});await load()},'secondary'));if(g.is_placeholder){[...actions.children].forEach((child,i)=>{if(i<3||child.tagName==='A')child.hidden=true})}if(!g.is_placeholder){actions.append(button('Baixar convite PNG',()=>downloadPng(g)),button('Baixar para impressão (SVG)',()=>downloadSvg(g),'secondary'),button('Imprimir / PDF',()=>printInvitations([g]),'secondary'))}card.append(actions);const group=g.group_name||'Sem grupo';if(!sections.has(group)){const section=el('details',undefined,'guest-group');section.open=true;const stats=groupStats(group);const summary=el('summary',`${group} — ${stats.people} pessoas · ${stats.yes} confirmadas`);section.append(summary);sections.set(group,section);list.append(section)}sections.get(group).append(card)}}catch(e){status.textContent=e.status===401?'Inicie sessão para gerir os convidados.':e.message;if(e.status===401){login.hidden=false;dashboard.hidden=true}}}
login.onsubmit=async e=>{e.preventDefault();const b=login.querySelector('button');b.disabled=true;try{await api('/api/admin/login',{method:'POST',body:{password:document.querySelector('#password').value}});document.querySelector('#password').value='';await load()}catch(err){status.textContent=err.message}finally{b.disabled=false}};
document.querySelector('#guest-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/guests',{method:'POST',body:{name:document.querySelector('#new-name').value,companion:document.querySelector('#new-companion').value,group_name:document.querySelector('#new-group').value,phone:document.querySelector('#new-phone').value}});e.target.reset();await load()}catch(err){await message(err.message)}finally{b.disabled=false}};
document.querySelector('#gift-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/gifts',{method:'POST',body:{name:document.querySelector('#gift-name').value,description:document.querySelector('#gift-description').value}});e.target.reset();await load()}catch(err){await message(err.message)}finally{b.disabled=false}};
document.querySelector('#search').oninput=renderGuests;document.querySelector('#filter').onchange=renderGuests;document.querySelector('#group-filter').onchange=renderGuests;document.querySelector('#refresh').onclick=load;
document.querySelector('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST',body:{}});dashboard.hidden=true;login.hidden=false;guests=[];document.querySelector('#guests').replaceChildren();document.querySelector('#admin-gifts').replaceChildren();status.textContent='Sessão terminada.'};
document.querySelector('#export').onclick=()=>{const safe=v=>{v=String(v??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'};const csv='\ufeff'+[['Grupo','Por nomear','Primeiro convidado','Acompanhante','Telefone','Presença','Presença acompanhante','Activo','Link'],...guests.map(g=>[g.group_name||'',g.is_placeholder?'Sim':'Não',g.name,g.companion||'',g.phone,labels[g.rsvp],g.companion?labels[g.companion_rsvp]:'',g.active?'Sim':'Não',invite(g)])].map(row=>row.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=el('a');a.href=url;a.download='convidados-aniceta-kerusso.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};load();

for(const tab of document.querySelectorAll('[data-panel]'))tab.onclick=()=>{for(const t of document.querySelectorAll('[data-panel]')){t.setAttribute('aria-selected',String(t===tab));document.querySelector('#'+t.dataset.panel).hidden=t!==tab}};
for(const node of document.querySelectorAll('[data-icon]'))node.prepend(icon(node.dataset.icon));

document.querySelector('#download-all').onclick=()=>{try{downloadAll(guests)}catch(e){message(e.message)}};document.querySelector('#print-all').onclick=()=>{try{printInvitations(guests)}catch(e){message(e.message)}};
